const preview = `<!doctype html><html lang="en" data-theme="light"><head><meta charset="utf-8"><title>CyberNest — Blogger foundation preview</title>${head.replace(/<!\[CDATA\[/g,'').replace(/\]\]>/g,'')}<style>${css}</style></head><body>${top.replace('__LINKS_WIDGET__','<div class="sidebar-custom-links"><div class="widget"><h2>Quick links</h2><ul><li><a href="'+appOrigin+'/vault/" target="_blank" rel="noopener noreferrer">CyberNest learning app ↗</a></li></ul></div></div>')}<div class="app-shell"><main class="main" id="main-content" tabindex="-1">${noscript}<div class="announcement-region" id="announcement-region"><div class="widget"><h2>Welcome to CyberNest</h2><div class="widget-content"><p>A space to keep learning, stay curious and build your next skill.</p></div></div></div><div id="workspace-content"></div><section class="native-blog" id="native-posts" aria-label="Published blog posts">${nativeHeading}${previewPosts}</section></main>${footer}</div><div class="route-announcer" id="route-announcer" aria-live="polite" aria-atomic="true"></div><script>${script.replace("function isNative(){return location.pathname!=='/'&&location.pathname!==''}","function isNative(){return false}")}</script></body></html>`;
